import{_ as t,a as o}from"./chunks/router-tree-navigate._pyF91bk.js";import{_ as r,o as i,c as a,aj as s}from"./chunks/framework.C6uXqnaX.js";const v=JSON.parse('{"title":"Inspect the Router Tree","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/devtools/router.md","filePath":"en/tools/devtools/router.md"}'),n={name:"en/tools/devtools/router.md"};function l(c,e,d,u,h,g){return i(),a("div",null,e[0]||(e[0]=[s('<h1 id="inspect-the-router-tree" tabindex="-1">Inspect the Router Tree <a class="header-anchor" href="#inspect-the-router-tree" aria-label="Permalink to &quot;Inspect the Router Tree&quot;">​</a></h1><p>The <strong>Router Tree</strong> tab lets you visualize the routing tree of your application. You can explore how routes are nested and view details about specific routes.</p><img src="'+t+'" alt="A screenshot of the &#39;Router Tree&#39; tab in Angular DevTools showing a tree of configured routes. The active routes are highlighted in green, while inactive ones are white."><h3 id="view-route-details" tabindex="-1">View route details <a class="header-anchor" href="#view-route-details" aria-label="Permalink to &quot;View route details&quot;">​</a></h3><p>When you select a specific route in the tree, Angular DevTools displays its properties in the sidebar on the right. This information includes:</p><ul><li><strong>Path</strong>: The URL path for the route. If the route uses a custom URL matcher, DevTools displays the <strong>Matcher</strong> instead.</li><li><strong>Component</strong>: The component rendered for this route. If the route is a redirect, DevTools displays the <strong>Redirect to</strong> target instead.</li><li><strong>Path Match</strong>: The path matching strategy (<code>prefix</code> or <code>full</code>), if configured.</li><li><strong>Data</strong>: Static data associated with the route, displayed as a JSON tree.</li><li><strong>Resolvers</strong>: Route resolvers, displayed as key-value pairs.</li><li><strong>Guards</strong>: Any guards configured on the route, grouped by type — <code>canActivate</code>, <code>canActivateChild</code>, <code>canDeactivate</code>, and <code>canMatch</code>.</li><li><strong>Providers</strong>: Route-level providers, if configured.</li><li><strong>Title</strong>: The route title, if configured.</li><li><strong>RunGuardsAndResolvers</strong>: The re-run strategy for guards and resolvers, if configured.</li><li><strong>Active</strong>: Whether this route is currently active.</li><li><strong>Auxiliary</strong>: Indicates if the route is an auxiliary route (e.g., in a named outlet).</li><li><strong>Lazy</strong>: Indicates if the route is lazily loaded.</li></ul><div class="info custom-block"><p class="custom-block-title">NOTE</p><p>Properties like Path Match, Data, Resolvers, Guards, Providers, Title, and RunGuardsAndResolvers only appear in the sidebar when they are configured on the selected route.</p></div><h3 id="navigate-to-a-specific-route" tabindex="-1">Navigate to a specific route <a class="header-anchor" href="#navigate-to-a-specific-route" aria-label="Permalink to &quot;Navigate to a specific route&quot;">​</a></h3><p>You can easily trigger navigation directly from the DevTools. While inspecting a route&#39;s details in the right sidebar, click on the <strong>Navigate</strong> icon next to the path string. This triggers the Angular router to navigate to that URL in your application.</p><img src="'+o+'" alt="A screenshot showing the &#39;Navigate to&#39; tooltip on the route path in the &#39;Routes Details&#39; sidebar.">',10)]))}const m=r(n,[["render",l]]);export{v as __pageData,m as default};
